theorem AdicCompletion.factor_evalₐ_eq_eval.{u_1} {R : Type u_1} [CommRing R] (I : Ideal R) {n : ℕ}
  (x : AdicCompletion I R) (h : I ^ n ≤ I ^ n • ⊤) :
  (Ideal.Quotient.factor h) ((AdicCompletion.evalₐ I n) x) = (AdicCompletion.eval I R n) x
